#!/usr/bin/env python3
import json
import subprocess
import sys

def get_issues(server):
    """Get issues from a SonarQube server via sonarless-mcp CLI"""
    cmd = f"sonarless-mcp issues --server {server} --json"
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        if result.returncode == 0:
            return json.loads(result.stdout) if result.stdout else {"issues": []}
        else:
            print(f"Error querying {server}: {result.stderr}", file=sys.stderr)
            return {"issues": []}
    except Exception as e:
        print(f"Exception querying {server}: {e}", file=sys.stderr)
        return {"issues": []}

# Get issues from both servers
local_data = get_issues("local")
remote_data = get_issues("work")

local_issues = local_data.get("issues", [])
remote_issues = remote_data.get("issues", [])

print(f"LOCAL: {len(local_issues)} issues")
for issue in local_issues[:10]:
    print(f"  - {issue.get('key')} [{issue.get('severity')}] {issue.get('message', '')[:60]}")
if len(local_issues) > 10:
    print(f"  ... and {len(local_issues) - 10} more")

print(f"\nREMOTE (CI): {len(remote_issues)} issues")
for issue in remote_issues[:10]:
    print(f"  - {issue.get('key')} [{issue.get('severity')}] {issue.get('message', '')[:60]}")
if len(remote_issues) > 10:
    print(f"  ... and {len(remote_issues) - 10} more")

# Compare
local_keys = {i.get('key') for i in local_issues}
remote_keys = {i.get('key') for i in remote_issues}

only_local = local_keys - remote_keys
only_remote = remote_keys - local_keys

print(f"\nOnly in local ({len(only_local)}):", only_local if only_local else "None")
print(f"Only in remote/CI ({len(only_remote)}):", only_remote if only_remote else "None")
EOF

